import{_ as i,l as r,o as e,c as s,v as o,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"LSM 读放大与布隆","description":"","frontmatter":{"title":"LSM 读放大与布隆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lsm-read-amplification.md","filePath":"cs/lsm-read-amplification.md","lastUpdated":1789023840000}'),m={name:"cs/lsm-read-amplification.md"};function B(E,a,h,_,f,S){const l=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="lsm-读放大与布隆" tabindex="-1">LSM 读放大与布隆 <a class="header-anchor" href="#lsm-读放大与布隆" aria-label="Permalink to &quot;LSM 读放大与布隆&quot;">​</a></h1><div class="epigraph"><p>点查可能打开每一层的文件；布隆过滤器以假阳性换「文件里肯定没有」的跳过，读放大才从层数里降下来。</p><footer>—— 据 Bloom, Space/Time Trade-offs in Hash Coding, CACM 1970；LevelDB/RocksDB；O&#39;Neil LSM</footer></div><p><a href="/cs/lsm-compaction">上一课</a>画出 memtable 与多层 SST。本课不选 compaction 形状。缺口是读路径：点查最坏触及每层多个文件（L0 重叠）。每文件一次 I/O 甚至一次索引块，放大远大于 B+ 的 \\(O(\\log n)\\) 页。布隆过滤器（及 fence 指针、区间）先否定「键不在此文件」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布隆：位图+多哈希，可能假阳性（空跑一次 I/O），无假阴性（说没有就真没有，对集合存在而言）。删除与墓碑：过滤器按文件构建时包含当时键；compaction 重建。缺口是<strong>把过滤器放进文件元数据</strong>，读路径先查内存里的布隆再决定是否读索引块。</p><p>范围扫描：布隆帮不上「范围内是否有键」的全体否定（有区间过滤器、prefix bloom 变体）。范围仍要走有序文件的迭代器堆（多路归并各层）。</p><p><span class="marginnote">Bloom 1970。计算机课布隆过滤器已有；本课接到 SST。quotient/cuckoo filter 是替代，点名不展开。假阳性率与位数是空间换 I/O。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个 SST 一块布隆（或按数据块分）。点查：从新到旧层，memtable → L0 各文件 → 更高层至多一个文件（leveled 时）。全 miss 仍可能因假阳性读盘。缓存索引块与布隆本身，避免过滤器也 miss。</p><p>统计：优化器对 LSM 表的代价应计期望打开文件数，不是当成堆扫。否则 DP 会误判。</p>',10)),(e(),n(c,null,{default:t(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E7%82%B9%E6%9F%A5%E9%94%AE%22%5D%20--%3E%20BF%5B%22%E6%96%87%E4%BB%B6%E5%B8%83%E9%9A%86%22%5D%0A%20%20BF%20--%3E%7C%22%E8%82%AF%E5%AE%9A%E6%97%A0%22%7C%20SKIP%5B%22%E8%B7%B3%E8%BF%87%E6%96%87%E4%BB%B6%22%5D%0A%20%20BF%20--%3E%7C%22%E5%8F%AF%E8%83%BD%E6%9C%89%22%7C%20IDX%5B%22%E8%AF%BB%E7%B4%A2%E5%BC%95%E5%9D%97%20%2F%20%E6%95%B0%E6%8D%AE%E5%9D%97%22%5D%0A%20%20SKIP%20--%3E%20NXT%5B%22%E4%B8%8B%E4%B8%80%E6%96%87%E4%BB%B6%E6%88%96%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>写放大与读放大此消彼长：更积极 compaction 减少层与重叠，读变好、写变重。布隆降低读放大但不降层数本身。块缓存命中时「打开文件」可能只是内存比较。</p><p>与延迟物化：SST 内部可以是行或列；布隆在键上，不在投影列上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较 leveled 与 tiered 的公式——下一课。也不把布隆当唯一跳过手段：zone map 在列存分析文件上做范围跳过，后课。</p><p>后课默认：LSM 点查先过滤器后数据；范围走多路迭代器。leveled 对 tiered：层内重叠政策不同，放大曲线不同。</p><p>假阳性是读放大的残余项，调位数直到 I/O 预算够。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>读放大来自多层与 L0 重叠；布隆跳过无键文件。</li><li>范围扫描主要靠有序归并，不是布隆。</li><li>leveled 对 tiered 下一课：compaction 形状决定放大。</li><li>出处：Bloom 1970；O&#39;Neil LSM；LevelDB/RocksDB。</li></ul>',9))])}const T=i(m,[["render",B]]);export{A as __pageData,T as default};
